sc_cat_item_producer.script:
(function() {
	if (producer.walk_in == "true") {
		producer.portal_redirect = "?id=hoc_ohsm_nurse_appt_confirmation&requestNumber=" + current.number;
    	//producer.portal_redirect = "/x_hccc_hoc_ohs_vaccination_appointment.do?sys_id="+ current.sys_id;
	}


    if (producer.who_are_you_booking_for == "myself" || //Process if myself
        producer.who_are_you_booking_for == "") {
        current.contact = gs.getUserID();
    } else if (producer.who_are_you_booking_for == "external") { //Process external user
        //check if this email exists in the contacts database.	
        current.contact = new x_hccc_hoc_ohs.HoCOHSMFluClinic()
            .createExternalContact(producer.first_name, producer.last_name, producer.email_address);
    } else if (producer.who_are_you_booking_for == "internal" || //Process internal employee
        producer.who_are_you_booking_for == "mp" ||
        producer.who_are_you_booking_for == "pps") {
        current.contact = producer.internal_employee;
    }


    //var copyAtt = new GlideSysAttachment(); 
    //copyAtt.copy("wu_appointment", "a81d86041bd3d5509fde86acdd4bcb7a", "wu_appointment", current.sys_id+""); //Case WUA0001104
    /*var gr = new GlideRecord('wu_appointment');
    //gr.get('a81d86041bd3d5509fde86acdd4bcb7a');
    gr.get('b15e6c381b175d502e79ba2d1e4bcb72'); //Prod value. Appointment WUA0001001
    gr.setValue('contact', current.getValue("contact"));
    gs.info("AMP: " + current.getValue("contact"));
    gr.update();*/ //commented out 2023-10-06

    function getLatestRevision(documentID) {
        var grRev = new GlideRecord('dms_document_revision');

        grRev.addQuery('document', documentID);
        grRev.orderByDesc('revision_number');
        grRev.query();
        grRev.next();

        return grRev;
    }

    function getDocumentObject(grDocRev) {
        var docObj = {};

        docObj.fileName = grDocRev.attachment.file_name.toString();
        docObj.contentType = grDocRev.attachment.content_type.toString();
        docObj.sysId = grDocRev.attachment.toString();

        return docObj;
    }

    function attachDocument(target, docObj) {
        var gsa = new GlideSysAttachment();

        return gsa.writeContentStream(
            target,
            docObj.fileName,
            docObj.contentType,
            gsa.getContentStream(docObj.sysId)
        );

        //works but can't change the name
        /*gsa.copy(
            'dms_document_revision',
            sourceCovidEn.getUniqueValue(),
            'wu_appointment',
            target.getUniqueValue()
        );*/
    }

    var CONSENT_DOCUMENT = {
        COVID19: {
            EN: '25a64a561b71fd909fde86acdd4bcba0',
            FR: '28b6ce161b71fd909fde86acdd4bcb7f'
        },
        FLU: {
            EN: '054602161b71fd909fde86acdd4bcb2d',
            FR: 'ec864a161b71fd909fde86acdd4bcb11'
        }
    };
    var REASON = {
        COVID19: 'bf469b141b7df9989fde86acdd4bcb79',
        FLU: '5926d3141b7df9989fde86acdd4bcb08',
        BOTH: 'e86617541b7df9989fde86acdd4bcbd8'
    };
	var reasonId = producer.reason.sys_id.getDisplayValue(); //sysId of the reason selected (as a string)

	gs.info(reasonId);
	gs.info(REASON.FLU);
	switch (reasonId) {
		case REASON.FLU: 
			current.short_description = 'Flu vaccine / Vaccin contre la grippe'; 
			gs.info('set flu short description')
			break;
		case REASON.COVID19:
			current.short_description = 'COVID-19 vaccine / Vaccin contre la COVID-19'; 
			break;
		default: 
			current.short_description = 'Both vaccines (Flu and COVID-19) / Deux vaccins (Grippe et COVID-19)';

	}

    /*gs.info("1-reasonDisplayValue: " + producer.reason.getDisplayValue()); //returns the text
    gs.info("reasonId: " + reasonId);
	gs.info("reasonId === FLU? " + (reasonId === REASON.FLU));
	gs.info("reasonId === COVID19? " + (reasonId === REASON.COVID19));
	gs.info("reasonId === REASON.both? " + (reasonId === REASON.BOTH));*/

    if (reasonId === REASON.FLU ||
        reasonId === REASON.BOTH) {
        var sourceFluEn = getLatestRevision(CONSENT_DOCUMENT.FLU.EN)
        var sourceFluFr = getLatestRevision(CONSENT_DOCUMENT.FLU.FR)
        var docFluEn = getDocumentObject(sourceFluEn);
        var docFluFr = getDocumentObject(sourceFluFr);

        docFluEn.fileName = "ConsentFormInfluenza.pdf";
        docFluFr.fileName = "FormulaireConsentementGrippe.pdf";

        attachDocument(current, docFluEn);
        attachDocument(current, docFluFr);
    }
    if (reasonId === REASON.COVID19 ||
        reasonId === REASON.BOTH) {
        var sourceCovidEn = getLatestRevision(CONSENT_DOCUMENT.COVID19.EN)
        var sourceCovidFr = getLatestRevision(CONSENT_DOCUMENT.COVID19.FR)
        var docCovEn = getDocumentObject(sourceCovidEn);
        var docCovFr = getDocumentObject(sourceCovidFr);

        docCovEn.fileName = "ConsentFormInCOVID.pdf";
        docCovFr.fileName = "FormulaireConsentementCOVID.pdf";

        attachDocument(current, docCovEn);
        attachDocument(current, docCovFr);
    }
})();
